def _release_cap(name: str, locked: int) -> int:
    """Return the env-configured cap for name, capped at locked, or locked if unset/invalid."""
    raw = os.environ.get(name, "").strip()
    if not raw:
        return locked
    try:
        value = int(raw)
    except ValueError:
        return locked
    if value < 1:
        return locked
    return min(value, locked)


